const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const clone=value=>structuredClone(value);
const pageName=page=>({'index.html':'Home','about.html':'Our Story','contact.html':'Contact','donate.html':'Donate','gallery.html':'Gallery','projects.html':'Our Projects','shop.html':'Shop'}[page.file]||(page.file.startsWith('projects/')?'Project: '+page.file.split('/').pop().replace('.html','') : page.title));
const pageOptions=()=>draft.pages.map((page,index)=>`<option value="${index}" ${index===pageIndex?'selected':''}>${esc(pageName(page))} (${esc(page.file)})</option>`).join('');
function selectPage(index){
 pageIndex=Number(index);
 if(!draft.pages[pageIndex])pageIndex=0;
 const firstContent=draft.pages[pageIndex].sections.findIndex(section=>!section.locked);
 sectionIndex=Math.max(0,firstContent);
 fieldQuery='';
}
let auth,model,draft,revision=0,view='overview',pageIndex=0,sectionIndex=0,dirty=false,previewMode='draft',device='desktop',mobileTab='content',fieldQuery='',mediaQuery='',mediaLimit=25,imageTarget=null,replaceMedia=null;
let undoStack=[],previewTimer,linkInventory={items:[]},linkQuery='',linkPage='',linkType='',linkLimit=60;
const views=[['overview','◈','Overview'],['pages','▤','Pages'],['events','◷','Projects & Events'],['media','▧','Gallery & Media'],['shop','▣','Shop & Orders'],['navigation','⇄','Navigation & Links'],['appearance','◉','Appearance'],['users','♙','Users & Settings']];
const can=area=>auth?.permissions?.includes(area);
const canPublish=()=>['Owner','Administrator'].includes(auth.user.role);
const changed=()=>{dirty=true;const node=$('[data-save-status]');if(node){node.textContent='● Unsaved changes';node.classList.add('dirty');}clearTimeout(previewTimer);previewTimer=setTimeout(sendPreview,350);};
function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('visible');clearTimeout(node._timer);node._timer=setTimeout(()=>node.classList.remove('visible'),5000);}
async function api(route,options={}){
 const response=await fetch('/api/admin/'+route,{...options,headers:{'Content-Type':'application/json',...(auth?.csrf?{'X-CSRF-Token':auth.csrf}:{}),...options.headers}});
 let data;try{data=await response.json();}catch{throw new Error('Start the management server with “npm run admin”, then open http://127.0.0.1:4173/admin/.');}
 if(!response.ok)throw new Error(data.error||'Request failed.');return data;
}
function confirmChange(title,message){const dialog=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;return new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();});}
const date=value=>new Date(value).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'})+' UTC';
const button=(label,action,style='secondary',extra='')=>`<button type="button" class="${style}" data-action="${action}" ${extra}>${label}</button>`;
const heading=(title,subtitle,actions='')=>`<div class="page-heading"><div><p class="eyebrow">LESHELTER STUDIO</p><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;
function formatKey(path){const parts=path.split('.');if(parts[0]==='pages'){const page=draft.pages[parts[1]],section=page?.sections[parts[3]];return ['pages',page?.id,section?.id,parts[4]==='fields'?section?.fields[parts[5]]?.id:parts[4]].join('.');}if(['products','navigation'].includes(parts[0]))parts[1]=draft[parts[0]][parts[1]]?.id;return parts.join('.');}
function textTools(path){
 const style=draft.textStyles?.[formatKey(path)]||{},disabled=!can(path.split('.')[0])?'disabled':'';
 const control=(property,type,value,extra='')=>`<input aria-label="${property}" title="${property}" type="${type}" data-format-path="${path}" data-format="${property}" value="${esc(value)}" ${disabled} ${extra}>`;
 return `<div class="text-tools" role="group" aria-label="Text formatting">${control('color','color',style.color||'#193d31')}${control('fontSize','number',style.fontSize||'','min="8" max="120" placeholder="px"')}<select aria-label="Font family" data-format-path="${path}" data-format="fontFamily" ${disabled}>${['','Inter, Arial, sans-serif','Georgia, serif','Arial, sans-serif','Verdana, sans-serif'].map(value=>`<option value="${value}" ${style.fontFamily===value?'selected':''}>${value?value.split(',')[0]:'Default font'}</option>`).join('')}</select><select aria-label="Text alignment" data-format-path="${path}" data-format="textAlign" ${disabled}>${['','left','center','right','justify'].map(value=>`<option value="${value}" ${style.textAlign===value?'selected':''}>${value||'Align'}</option>`).join('')}</select>${[['fontWeight','700','B'],['fontStyle','italic','I'],['textDecoration','underline','U']].map(([property,value,label])=>`<button type="button" class="${style[property]===value?'selected':'secondary'}" data-format-path="${path}" data-format="${property}" data-format-value="${style[property]===value?'':value}" ${disabled} aria-label="${property}" aria-pressed="${style[property]===value}">${label}</button>`).join('')}<button type="button" class="quiet" data-format-reset="${path}" ${disabled}>Reset</button></div>`;
}
function field(label,path,value,type='text',extra=''){
 const area=path.split('.')[0],disabled=!can(area)?'disabled':'';
 return `<div class="field"><label>${esc(label)}</label>${['text','textarea'].includes(type)&&!/(?:image|imageAlt|buttonUrl|flyer|url|hex|alt)$/.test(path)?textTools(path):''}${type==='textarea'?`<textarea data-bind="${path}" ${disabled} ${extra}>${esc(value)}</textarea>`:`<input type="${type}" data-bind="${path}" value="${esc(value)}" ${disabled} ${extra}>`}</div>`;
}
function getPath(object,path){return path.split('.').reduce((value,key)=>value?.[key],object);}
function setPath(object,path,value){const keys=path.split('.');let target=object;for(const key of keys.slice(0,-1)){if(['__proto__','constructor','prototype'].includes(key))return;target=target[key];}target[keys.at(-1)]=value;}
function checkpoint(){undoStack.push(clone(draft));if(undoStack.length>20)undoStack.shift();}
async function load(){[model,linkInventory]=await Promise.all([api('state'),api('links')]);draft=clone(model.draft);revision=model.revision;auth.permissions=model.permissions;dirty=false;undoStack=[];selectPage(pageIndex);render();}
function authScreen(setup,error=''){
 $('#app').innerHTML=`<main class="auth-wrap"><section class="auth-art"><img src="/images/Logo.png" alt="Le Shelter Foundation"><p class="local-label">YOUR PURPOSE. YOUR PLATFORM.</p><h1>A little care.<br>A lasting impact.</h1><p>Manage your stories, connect your community and shape the next chapter of LeShelter.</p></section><section class="auth-card"><p class="eyebrow">LESHELTER STUDIO</p><h1>${setup?'Make yourself at home.':'Welcome back.'}</h1><p class="muted">${setup?'Create the first owner account for this website.':'Sign in to manage your website.'}</p><form data-auth="${setup?'setup':'login'}">${setup?'<div class="field"><label for="auth-name">Your name</label><input id="auth-name" name="name" required autocomplete="name"></div>':''}<div class="field"><label for="auth-email">Email address</label><input id="auth-email" type="email" name="email" required autocomplete="username"></div><div class="field"><label for="auth-password">Password ${setup?'(at least 12 characters)':''}</label><input id="auth-password" type="password" name="password" required minlength="${setup?12:1}" maxlength="200" autocomplete="${setup?'new-password':'current-password'}"></div><button>${setup?'Create owner account':'Sign in'}</button><p class="error" role="alert">${esc(error)}</p></form><p class="muted small" style="margin-top:25px">${auth?.storage==='supabase'?'Cloud management: Drafts are private. Publishing updates the live website content.':'Local management server: Drafts are private. Publishing updates workspace website files.'}</p></section></main>`;
}
function render(){
 if(!draft)return;
 const title=views.find(item=>item[0]===view)?.[2]||'Preview';
 $('#app').innerHTML=`<div class="shell"><button class="screen-shade" data-action="drawer" aria-label="Close navigation"></button><aside class="sidebar"><div class="brand"><img src="/images/icon.png" alt=""><div><strong>LeShelter</strong><small>Website studio</small></div></div><p class="nav-label">WORKSPACE</p><nav aria-label="Dashboard">${views.map(([id,icon,name])=>`<button class="${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${name}</button>`).join('')}<a href="/admin/members.html" target="_blank" rel="noopener" style="display:block;padding:14px">Members &amp; IDs</a></nav><div class="sidebar-bottom"><strong>${esc(auth.user.name)}</strong>${esc(auth.user.role)} · ${auth.storage==='supabase'?'Cloud workspace':'Local workspace'}<div class="actions" style="margin-top:12px"><a href="/index.html" target="_blank" rel="noopener">View website ↗</a><button class="quiet" data-action="logout">Sign out</button></div></div></aside><div class="workspace"><header class="topbar"><button class="quiet menu-button" data-action="drawer" aria-label="Toggle navigation">☰</button><p class="breadcrumbs">Workspace / <strong>${esc(title)}</strong></p><div class="top-actions"><span class="save-state ${dirty?'dirty':''}" data-save-status>${dirty?'● Unsaved changes':'✓ Saved draft'}</span>${button('Preview ↗','preview')}${button('Save draft','save','',!auth.permissions.length?'disabled':'')}${canPublish()?button('Publish','publish','secondary'):auth.user.role==='Editor'?button('Submit','submit','secondary'):''}</div></header><main class="main">${viewContent()}</main></div></div>`;
 const frame=$('#site-preview');if(frame){frame.addEventListener('load',sendPreview);}
}
function overview(){
 const edits=model.audit.slice(0,5);
 return heading('A good day to make a difference.', 'Your website, your community, all in one place.',button('Edit homepage','home',''))+`<div class="welcome"><div><p class="eyebrow" style="color:#c4d6b9">YOUR NEXT CHAPTER STARTS HERE</p><h2>Bring your purpose to life.</h2><p>Keep your pages fresh, share community stories and help more people find their place with LeShelter.</p></div>${button('Manage projects ↗','events','yellow')}</div><div class="stats-grid">${[['Published pages',model.published.pages.length,'Editable website pages','▤'],['Media library',draft.media.length,'Photos ready for your stories','▧'],['Next event',new Date(draft.event.start).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}),draft.event.location,'◷'],['Pending orders','—','Google Sheets orders are not connected','▣']].map(([label,value,note,icon])=>`<div class="stat"><span class="stat-icon">${icon}</span><p>${label}</p><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`).join('')}</div><div class="dashboard-columns"><section class="panel"><div class="panel-heading"><h2>Your pages</h2>${button('View all','pages','quiet')}</div>${draft.pages.slice(0,6).map((page,index)=>`<div class="page-row"><div><strong>${esc(page.title)}</strong><small>${page.sections.length} sections · ${page.file}</small></div>${button('Edit page →','editpage','quiet',`data-index="${index}"`)}</div>`).join('')}</section><div><section class="panel"><div class="panel-heading"><h2>Recent activity</h2><span class="tag">Audit log</span></div>${edits.length?edits.map(edit=>`<div class="activity"><div><strong>${esc(edit.action)}</strong><small>${esc(edit.user)}</small></div><small>${date(edit.at)}</small></div>`).join(''):'<p class="muted">Your saved changes and publishing activity will appear here.</p>'}</section><section class="panel"><p class="eyebrow">QUICK ACTIONS</p><div class="actions">${button('Add a section','addsection')}${button('Upload images','media')}${button('Event countdown','events')}</div></section></div></div>`;
}
function preview(){
 const page=draft.pages[pageIndex];
 return `<div class="preview-panel"><div class="preview-toolbar"><div class="actions">${['desktop','tablet','mobile'].map(size=>button(size==='desktop'?'▤ Desktop':size==='tablet'?'▯ Tablet':'▯ Mobile','device',device===size?'selected':'quiet',`data-size="${size}"`)).join('')}</div><select aria-label="Preview version" data-preview-version style="width:110px;font-size:10px;padding:5px"><option value="draft" ${previewMode==='draft'?'selected':''}>Draft</option><option value="published" ${previewMode==='published'?'selected':''}>Published</option></select></div><div class="preview-stage"><iframe id="site-preview" title="${esc(page.title)} preview" src="/${page.file}?cms-preview=1" sandbox="allow-scripts allow-same-origin" style="width:${device==='mobile'?'375px':device==='tablet'?'768px':'100%'}"></iframe></div><p class="preview-caption">${previewMode==='draft'?'Unsaved draft':'Last published content'} · Interactions are disabled in preview.</p></div>`;
}
function pagesView(){
 const page=draft.pages[pageIndex];sectionIndex=Math.min(sectionIndex,page.sections.length-1);const section=page.sections[sectionIndex];
 const select=`<select aria-label="Choose page" data-page-select style="max-width:440px">${pageOptions()}</select><a href="/${esc(page.file)}" target="_blank" rel="noopener">Open ${esc(pageName(page))} ↗</a>`;
 let fields='';
 if(section){
  const base=`pages.${pageIndex}.sections.${sectionIndex}`;
  if(section.custom){fields=field('Section title',base+'.title',section.title)+field('Description',base+'.description',section.description,'textarea')+field('Image path',base+'.image',section.image)+field('Image description',base+'.imageAlt',section.imageAlt)+field('Button label',base+'.buttonLabel',section.buttonLabel)+field('Button destination',base+'.buttonUrl',section.buttonUrl);}
  else fields=section.fields.filter(f=>!fieldQuery||`${f.label} ${f.value}`.toLowerCase().includes(fieldQuery.toLowerCase())).map(f=>{
    const index=section.fields.indexOf(f),path=base+`.fields.${index}.value`;
    return `<div class="field"><label>${esc(f.label)}</label>${f.attribute==='text'?textTools(path):''}${f.type==='image'?`<div class="image-field"><img src="${assetURL(f.value,page.file)}" alt=""><div style="flex:1"><input data-bind="${path}" value="${esc(f.value)}" ${!can('pages')?'disabled':''}>${button('Choose from library','pickimage','quiet',`data-path="${path}" ${!can('pages')?'disabled':''}`)}</div></div>`:f.attribute==='text'&&f.value.length>100?`<textarea data-bind="${path}" ${!can('pages')?'disabled':''}>${esc(f.value)}</textarea>`:`<input data-bind="${path}" value="${esc(f.value)}" ${!can('pages')?'disabled':''}>`}</div>`;
  }).join('');
 }
 return heading('Page editor ? '+pageName(page),'Select a section, edit its content and check your preview.',`${button('Undo','undo','secondary',undoStack.length?'':'disabled')}${button('+ Add section','addsection','',can('pages')?'':'disabled')}`)+`<div class="editor-toolbar">${select}<span class="tag">${page.sections.length} sections</span></div><div class="preview-tabs">${button('Content','mobilecontent')}${button('Preview','mobilepreview')}</div><div class="section-list" role="tablist" aria-label="Page sections"><p class="eyebrow">PAGE SECTIONS</p>${page.sections.map((s,i)=>`<div class="section-item ${i===sectionIndex?'active':''}" data-action="selectsection" data-index="${i}" role="tab" aria-selected="${i===sectionIndex}" tabindex="0"><strong>${esc(s.label||s.title)}</strong><small>${s.locked?'Shared layout':s.hidden?'Hidden':'Visible'}${s.sourceId?' · Duplicate':''}</small><div class="section-tools">${!s.locked?`${button('↑','upsection','quiet',`data-index="${i}" aria-label="Move section up" ${!can('pages')||i===0?'disabled':''}`)}${button('↓','downsection','quiet',`data-index="${i}" aria-label="Move section down" ${!can('pages')||i===page.sections.length-1?'disabled':''}`)}${button('⧉','duplicatesection','quiet',`data-index="${i}" aria-label="Duplicate section" ${!can('pages')?'disabled':''}`)}${button(s.hidden?'Show':'Hide','hidesection','quiet',`data-index="${i}" ${!can('pages')?'disabled':''}`)}${button('×','deletesection','quiet',`data-index="${i}" aria-label="Delete section" ${!can('pages')?'disabled':''}`)}`:''}</div></div>`).join('')}</div><div class="editor-layout mobile-${mobileTab}"><div class="field-editor"><h3 style="margin-bottom:15px">${esc(section?.label||section?.title||'Select a section')}</h3><input class="field-search" type="search" placeholder="Find a field…" aria-label="Find a field" value="${esc(fieldQuery)}" data-field-search><div data-fields>${fields||'<p class="muted">No matching editable fields.</p>'}</div></div>${preview()}</div>`;
}
function eventsView(){return heading('Projects & events','Manage the featured event and carousel behaviour.',button('Edit project pages','projectpages'))+`<div class="two-columns"><section class="panel"><h2 style="margin-bottom:22px">Featured event</h2><div class="form-grid">${field('Event title','event.title',draft.event.title,'text','class="full"')}${field('Start date & time (UTC)','event.start',draft.event.start.slice(0,16),'datetime-local','data-utc')}${field('End date & time (UTC)','event.end',draft.event.end.slice(0,16),'datetime-local','data-utc')}${field('Location','event.location',draft.event.location)}${field('Category','event.category',draft.event.category)}<div class="full">${field('Flyer image path','event.flyer',draft.event.flyer)}<img src="${assetURL(draft.event.flyer)}" alt="Event flyer" style="width:160px;border-radius:7px"></div></div></section><div><section class="panel"><h2 style="margin-bottom:22px">Carousel timing</h2>${Object.entries(draft.timing).map(([key,value])=>field(({hero:'Homepage hero (milliseconds)',circles:'Circular images (milliseconds)',testimonials:'Testimonials (milliseconds)'})[key],'timing.'+key,value,'number','min="1000" max="60000" step="500"')).join('')}<p class="muted small">1,000 milliseconds = 1 second. Reduced-motion preferences are respected.</p></section><section class="panel"><h2>Project stories</h2><p class="muted small" style="margin:12px 0">Manage project headings, images and links in their individual page sections.</p>${draft.pages.filter(p=>p.file.startsWith('projects/')).map(p=>`<div class="page-row"><strong>${esc(p.title)}</strong>${button('Edit','editpage','quiet',`data-index="${draft.pages.indexOf(p)}"`)}</div>`).join('')}</section></div></div>`;}
function mediaUsage(url){const uses=draft.pages.flatMap(p=>p.sections.flatMap(s=>[...(s.fields||[]).filter(f=>f.attribute==='src'&&normalizePath(f.value)===normalizePath(url)).map(()=>p.title),...(s.custom&&normalizePath(s.image||'')===normalizePath(url)?[p.title]:[])]));if(normalizePath(draft.event.flyer)===normalizePath(url))uses.push('Featured event');for(const product of draft.products){if(normalizePath(product.image||'')===normalizePath(url))uses.push('Product: '+product.name);for(const color of product.colors||[])if(normalizePath(color.image||'')===normalizePath(url))uses.push(product.name+' - '+color.name);}return uses;}
const normalizePath=value=>value.replace(/^\.\.\//,'').replace(/^\//,'');
function assetURL(value,file='index.html'){try{return new URL(value,new URL('/'+file,location.origin)).href;}catch{return '';}}
function mediaView(){
 const media=draft.media.filter(item=>`${item.alt} ${item.url} ${item.folder}`.toLowerCase().includes(mediaQuery.toLowerCase()));
 return heading('Gallery & media','Your images, organised and ready for every story.',button('↑ Upload image','upload','',can('media')?'':'disabled'))+`<input type="file" id="media-upload" accept="image/png,image/jpeg,image/webp" hidden><div class="editor-toolbar"><input type="search" data-media-search placeholder="Search images, descriptions or folders…" value="${esc(mediaQuery)}" style="max-width:400px" aria-label="Search media"><span class="tag">${media.length} images</span></div>${imageTarget?'<div class="notice">Choose “Use image” to insert a photo into the page field you selected.</div>':''}<div class="media-grid">${media.slice(0,mediaLimit).map(item=>{const index=draft.media.indexOf(item),uses=mediaUsage(item.url);return `<article class="media-card"><img src="/${esc(normalizePath(item.url))}" alt="${esc(item.alt)}" loading="lazy"><div><strong>${esc(item.url.split('/').at(-1))}</strong><small>${esc(item.folder)} · Used ${uses.length} times</small><p class="small muted" style="margin-top:6px">${esc(item.alt)}</p><div class="actions">${imageTarget?button('Use image','useimage','',`data-index="${index}"`):''}${button('Edit','editmedia','secondary',`data-index="${index}" ${!can('media')?'disabled':''}`)}${button('Replace','replacemedia','secondary',`data-index="${index}" ${!can('media')?'disabled':''}`)}${button('Remove','deletemedia','quiet',`data-index="${index}" ${!can('media')?'disabled':''}`)}</div></div></article>`;}).join('')}</div>${media.length>mediaLimit?`<div style="text-align:center;margin-top:25px">${button('Load more images','moremedia')}</div>`:''}`;
}
function productColors(product,i){return `<div style="margin-top:20px"><div class="panel-heading"><h3>Color photos</h3>${button('+ Add color','addcolor','secondary',`data-index="${i}" ${!can('products')?'disabled':''}`)}</div><p class="small muted">Each color can have its own photo. An empty photo uses the main product image.</p>${(product.colors||[]).map((color,j)=>`<div class="panel" style="margin-top:12px"><div class="form-grid">${field('Color name',`products.${i}.colors.${j}.name`,color.name)}${field('Swatch color',`products.${i}.colors.${j}.hex`,color.hex,'color')}${field('Photo description',`products.${i}.colors.${j}.alt`,color.alt||'')}</div><div class="image-field">${color.image?`<img src="${esc(assetURL(color.image,'shop.html'))}" alt="${esc(color.alt)}">`:'<span class="small muted">Uses main photo</span>'}<div class="actions">${button('Upload color photo','uploadproduct','secondary',`data-index="${i}" data-color="${j}" ${!can('products')||!can('media')?'disabled':''}`)}${button('Choose from library','pickimage','secondary',`data-path="products.${i}.colors.${j}.image" ${!can('products')?'disabled':''}`)}${button('Remove color','deletecolor','quiet',`data-index="${i}" data-color="${j}" ${!can('products')?'disabled':''}`)}</div></div>${field('Color photo path',`products.${i}.colors.${j}.image`,color.image||'')}</div>`).join('')}</div>`;}
function shopView(){return heading('Shop & orders','Add merchandise, organise filter categories and upload product photos.',button('+ Add product','addproduct','',can('products')?'':'disabled')+button('Preview shop','previewshop'))+`<input type="file" id="product-upload" accept="image/png,image/jpeg,image/webp" hidden><div class="notice">Save your draft to keep edits, then publish to update the website. Orders use the existing checkout connection.</div><datalist id="product-categories">${[...new Set(['Apparel','Accessories','Home & Gifts',...draft.products.map(p=>p.category)])].map(category=>`<option value="${esc(category)}">`).join('')}</datalist><div class="two-columns">${draft.products.map((product,i)=>`<section class="panel"><div class="panel-heading"><h2>${esc(product.name)}</h2>${button('Remove','deleteproduct','quiet',`data-index="${i}" ${!can('products')?'disabled':''}`)}</div><div class="form-grid">${field('Product name',`products.${i}.name`,product.name)}${field('Price (GHS)',`products.${i}.price`,product.price,'number','min="0" max="100000" step=".01"')}${field('Filter category',`products.${i}.category`,product.category,'text','list="product-categories" maxlength="60"')}${field('Image description',`products.${i}.imageAlt`,product.imageAlt)}</div>${field('Description',`products.${i}.description`,product.description,'textarea')}<div class="image-field">${product.image?`<img src="${esc(assetURL(product.image,'shop.html'))}" alt="${esc(product.imageAlt)}">`:'<p class="muted">No product photo yet</p>'}<div class="actions">${button('Upload photo','uploadproduct','secondary',`data-index="${i}" ${!can('products')||!can('media')?'disabled':''}`)}${button('Choose from library','pickimage','secondary',`data-path="products.${i}.image" ${!can('products')?'disabled':''}`)}</div></div>${field('Image path',`products.${i}.image`,product.image)}${productColors(product,i)}</section>`).join('')}</div>`;}

function websiteLinkRows(){
 const rows=[];
 for(const page of draft.pages){
  const pageIndex=draft.pages.indexOf(page);
  for(const item of linkInventory.items.filter(item=>item.file===page.file)){
   let sectionIndex=-1,labelPath='',hrefPath='',label=item.label,href=item.href,section='Page layout / interactive controls';
   for(const [index,part]of page.sections.entries()){
    const labelField=part.fields?.find(field=>field.key===item.key&&field.attribute==='text');
    const hrefField=part.fields?.find(field=>field.key===item.key&&field.attribute==='href');
    if(labelField||hrefField){sectionIndex=index;section=part.label||part.title;const base=`pages.${pageIndex}.sections.${index}.fields.`;
     if(labelField){label=labelField.value;labelPath=base+part.fields.indexOf(labelField)+'.value';}
     if(hrefField){href=hrefField.value;hrefPath=base+part.fields.indexOf(hrefField)+'.value';}break;
    }
   }
   if(item.menu){const index=draft.navigation.findIndex(link=>link.url.replace(/^\.\.\//,'')===item.href.replace(/^\.\.\//,''));if(index>=0){label=draft.navigation[index].label;href=draft.navigation[index].url;labelPath=`navigation.${index}.label`;hrefPath=`navigation.${index}.url`;section='Shared navigation';}}
   rows.push({...item,label,href,labelPath,hrefPath,section,pageIndex,sectionIndex});
  }
  if(page.file==='shop.html'){
   for(const product of draft.products)if(!rows.some(item=>item.file===page.file&&item.action===product.id))rows.push({id:'product-'+product.id,file:page.file,type:'Button',label:'Add to cart: '+product.name,href:'',section:'Product catalog',action:'Add product to cart',pageIndex,sectionIndex:-1});
   const categories=[...new Set(draft.products.map(product=>product.category))];
   for(const category of categories)if(!rows.some(item=>item.file===page.file&&item.label.toLowerCase().includes(category.toLowerCase())))rows.push({id:'category-'+category,file:page.file,type:'Button',label:category,href:'',section:'Product filters',action:'Filter products by category',pageIndex,sectionIndex:-1});
  }
  page.sections.forEach((part,index)=>{if(part.custom&&part.buttonLabel)rows.push({id:part.id,file:page.file,type:'Link',label:part.buttonLabel,href:part.buttonUrl,section:part.title||'Custom section',pageIndex,sectionIndex:index,labelPath:`pages.${pageIndex}.sections.${index}.buttonLabel`,hrefPath:`pages.${pageIndex}.sections.${index}.buttonUrl`});});
  rows.push({id:page.id+'-whatsapp',file:page.file,type:'Link',label:'Chat with us (floating WhatsApp)',href:'https://wa.me/233530449325',section:'Shared floating widget',pageIndex,sectionIndex:-1});
 }
 return rows;
}
function navigationView(){
 const all=websiteLinkRows(),rows=all.filter(item=>(!linkPage||item.file===linkPage)&&(!linkType||item.type===linkType)&&(!linkQuery||[item.label,item.href,item.section,item.file].join(' ').toLowerCase().includes(linkQuery.toLowerCase())));
 return mainNavigationView()+`<section class="panel"><div class="panel-heading"><h2>All website buttons & links</h2><span class="tag">${rows.length} of ${all.length}</span></div><div class="link-filters"><input type="search" data-link-search aria-label="Search website links" placeholder="Search labels, destinations or sections" value="${esc(linkQuery)}"><select data-link-page aria-label="Filter links by page"><option value="">All pages</option>${draft.pages.map(page=>`<option value="${esc(page.file)}" ${page.file===linkPage?'selected':''}>${esc(pageName(page))}</option>`).join('')}</select><select data-link-type aria-label="Filter by control type"><option value="">Buttons & links</option>${['Link','Button'].map(type=>`<option ${type===linkType?'selected':''}>${type}</option>`).join('')}</select></div><p class="small muted">Links have destinations. Action buttons run features such as checkout, filters or galleries; their behaviour stays attached to those features. Shared menu edits use the main navigation settings above.</p><div class="website-link-list">${rows.slice(0,linkLimit).map(item=>`<article class="website-link-row"><div><span class="tag">${item.type}</span><strong>${esc(pageName(draft.pages[item.pageIndex]))}</strong><small>${esc(item.file)} / ${esc(item.section)}</small></div><div>${item.labelPath?field('Label',item.labelPath,item.label):`<label>Label</label><p>${esc(item.label)}</p>`}</div><div>${item.hrefPath?field('Destination',item.hrefPath,item.href):`<label>${item.type==='Button'?'Action':'Destination'}</label><p class="small">${esc(item.type==='Button'?(item.action||'Website interaction'):item.href)}</p>`}</div><div>${item.sectionIndex>=0?button('Open section','linksection','secondary',`data-index="${item.pageIndex}" data-section="${item.sectionIndex}"`):''}</div></article>`).join('')||'<p class="empty">No matching links or buttons.</p>'}</div>${rows.length>linkLimit?button('Show more','morelinks','secondary'):''}</section>`;
}
function mainNavigationView(){return heading('Navigation & links','Keep your visitors moving in the right direction.',button('+ Add link','addnav','',can('navigation')?'':'disabled'))+`<section class="panel"><h2 style="margin-bottom:15px">Main navigation</h2>${draft.navigation.map((item,i)=>`<div class="nav-row"><div>${textTools(`navigation.${i}.label`)}<input aria-label="Link label" data-bind="navigation.${i}.label" value="${esc(item.label)}" ${!can('navigation')?'disabled':''}></div><input aria-label="Link destination" data-bind="navigation.${i}.url" value="${esc(item.url)}" ${!can('navigation')?'disabled':''}><div class="actions">${button('↑','upnav','secondary',`data-index="${i}" ${!can('navigation')||!i?'disabled':''} aria-label="Move link up"`)}${button('↓','downnav','secondary',`data-index="${i}" ${!can('navigation')||i===draft.navigation.length-1?'disabled':''} aria-label="Move link down"`)}${button('×','deletenav','secondary',`data-index="${i}" ${!can('navigation')?'disabled':''} aria-label="Delete link"`)}</div></div>`).join('')}<p class="small muted" style="margin-top:20px">This list controls the shared desktop and mobile website navigation. Use the website-wide list below to edit page links and button labels.</p></section>`;}
function appearanceView(){return heading('Appearance','Familiar colours. A consistent experience.')+`<div class="two-columns"><section class="panel"><h2>Brand palette</h2>${Object.entries(draft.theme).map(([name,value])=>`<div class="theme-row"><div><strong>${esc(name[0].toUpperCase()+name.slice(1))}</strong><p class="small muted">Shared website colour</p></div><input aria-label="${name} colour" type="color" data-bind="theme.${name}" value="${value}" ${!can('theme')?'disabled':''}><input aria-label="${name} hex colour" data-bind="theme.${name}" value="${value}" pattern="#[0-9a-fA-F]{6}" ${!can('theme')?'disabled':''}></div>`).join('')}<div id="contrast-readout"></div></section><section class="panel"><p class="eyebrow">TYPE & COLOUR PREVIEW</p><div id="theme-sample" style="padding:25px;border-radius:8px"><h1>A little support.<br>A lifetime of possibility.</h1><p style="margin-top:18px">Readable typography and considered contrast help everyone feel welcome.</p><button style="margin-top:22px" id="theme-button">Make a difference ↗</button></div><p class="small muted" style="margin-top:20px">Inter remains the dashboard font. Website headings retain their existing serif styling.</p></section></div>`;}
function usersView(){return heading('Users & settings','The right access for every member of your team.')+`<div class="two-columns"><div><section class="panel"><h2 style="margin-bottom:18px">Team access</h2>${auth.user.role==='Owner'?`<table class="table"><thead><tr><th>Team member</th><th>Role</th><th>Access</th></tr></thead><tbody>${model.users.map(user=>`<tr><td><strong>${esc(user.name)}</strong><small>${esc(user.email)}</small></td><td>${esc(user.role)}</td><td>${user.id===auth.user.id?'<span class="tag">You</span>':button('Edit access','edituser','secondary',`data-id="${user.id}"`)+button('Remove','removeuser','quiet',`data-id="${user.id}"`)}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">Only the Owner can manage user accounts and access.</p>'}</section>${auth.user.role==='Owner'?`<section class="panel"><h2 style="margin-bottom:20px">Add team member</h2><form data-user-form><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Initial password (12+ characters)</label><input type="password" name="password" minlength="12" maxlength="200" required autocomplete="new-password"></div><div class="field"><label>Role</label><select name="role">${['Administrator','Editor','Viewer','Owner'].map(role=>`<option>${role}</option>`).join('')}</select></div></div><button>Add team member</button></form></section>`:''}<section class="panel"><h2>Roles</h2><div class="role-guide"><p><strong>Owner:</strong> all content, publishing and team access.</p><p><strong>Administrator:</strong> all website content and publishing.</p><p><strong>Editor:</strong> page content, media, links and events; submit drafts for approval.</p><p><strong>Viewer:</strong> review content and preview only.</p><p>Additional per-area restrictions are enforced by the server.</p></div></section></div><div><section class="panel"><h2 style="margin-bottom:15px">Revision history</h2>${model.history.length?model.history.slice(0,15).map(item=>`<div class="activity"><div><strong>${esc(item.label)}</strong><small>${date(item.at)} · ${esc(item.user)}</small></div>${canPublish()?button('Restore','restore','quiet',`data-id="${item.id}"`):''}</div>`).join(''):'<p class="muted">Your saved revisions will appear here.</p>'}</section><section class="panel"><h2 style="margin-bottom:15px">Audit log</h2>${model.audit.slice(0,20).map(item=>`<div class="activity"><div><strong>${esc(item.action)}</strong><small>${esc(item.user)} · ${date(item.at)}</small></div></div>`).join('')}</section></div></div>`;}
function viewContent(){switch(view){case'overview':return overview();case'pages':return pagesView();case'events':return eventsView();case'media':return mediaView();case'shop':return shopView();case'navigation':return navigationView();case'appearance':setTimeout(updateContrast);return appearanceView();case'users':return usersView();case'preview':return heading('Preview your next chapter.','Compare your working draft with the last published website.',button('Back to editor','pages'))+`<div class="editor-toolbar"><select data-page-select aria-label="Preview page" style="max-width:400px">${pageOptions()}</select></div><div class="preview-only">${preview()}</div>`;default:return'';}}
function sendPreview(){const frame=$('#site-preview');if(frame)frame.contentWindow.postMessage({type:'leshelter-preview',content:previewMode==='published'?model.published:draft},location.origin);}
window.addEventListener('message',event=>{if(event.origin===location.origin&&event.source===$('#site-preview')?.contentWindow&&event.data?.type==='leshelter-preview-ready')sendPreview();});
function updateContrast(){
 const node=$('#contrast-readout');if(!node)return;
 const luminance=hex=>{const values=hex.slice(1).match(/../g)?.map(value=>parseInt(value,16)/255);if(!values||values.some(Number.isNaN))return 0;const linear=values.map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return linear[0]*.2126+linear[1]*.7152+linear[2]*.0722;};
 const a=luminance(draft.theme.text),b=luminance(draft.theme.background),ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);
 node.innerHTML=`<div class="contrast" style="background:${esc(draft.theme.background)};color:${esc(draft.theme.text)};border:1px solid #dfe6dc"><strong>${ratio.toFixed(2)}:1 contrast</strong><p class="small">${ratio>=4.5?'Passes normal-text contrast target.':'Below the 4.5:1 normal-text contrast target.'}</p></div>`;
 const sample=$('#theme-sample');sample.style.background=draft.theme.background;sample.style.color=draft.theme.text;$('#theme-button').style.background=draft.theme.primary;
}
async function save(){if(!auth.permissions.length)return;const result=await api('draft',{method:'PUT',body:JSON.stringify({draft,revision})});revision=result.revision;dirty=false;model.draft=clone(draft);toast('Draft saved. The public website is unchanged.');model=await api('state');render();}
async function action(name,node){
 const index=Number(node?.dataset.index),page=draft.pages[pageIndex],list=page.sections;
 if(views.some(v=>v[0]===name)){view=name;render();return;}
 switch(name){
 case'drawer':$('.shell').classList.toggle('drawer-open');break;
 case'home':selectPage(draft.pages.findIndex(p=>p.file==='index.html'));view='pages';render();break;
 case'editpage':selectPage(index);view='pages';render();break;
 case'projectpages':selectPage(draft.pages.findIndex(p=>p.file.startsWith('projects/')));view='pages';render();break;
 case'shoppage':selectPage(draft.pages.findIndex(p=>p.file==='shop.html'));view='pages';render();break;
 case'preview':view='preview';render();break;
 case'device':device=node.dataset.size;render();break;
 case'mobilecontent':mobileTab='content';render();break;
 case'mobilepreview':mobileTab='preview';render();break;
 case'selectsection':sectionIndex=index;fieldQuery='';render();break;
 case'save':await save();break;
 case'publish':if(dirty){toast('Save your draft before publishing.');break;}if(await confirmChange('Publish this saved draft?',auth.storage==='supabase'?'This publishes the saved draft to the live website.':'This updates the public content file in your workspace. Online hosting still requires your normal deployment.')){await api('publish',{method:'POST',body:JSON.stringify({revision})});await load();toast(auth.storage==='supabase'?'Published to the live website.':'Published to workspace website files.');}break;
 case'submit':if(dirty){toast('Save your draft before submitting.');break;}await api('submit',{method:'POST',body:'{}'});await load();toast('Saved draft submitted for review.');break;
 case'logout':if(dirty&&!await confirmChange('Discard unsaved changes?','Saved drafts will remain. Unsaved edits in this session will be lost.'))return;await api('logout',{method:'POST',body:'{}'});authScreen(false);draft=null;break;
 case'undo':if(undoStack.length){draft=undoStack.pop();changed();render();}break;
 case'addsection':if(!can('pages'))return;checkpoint();list.splice(Math.max(0,list.length-1),0,{id:'custom-'+Date.now(),custom:true,label:'New section',title:'A new chapter',description:'Tell your community what comes next.',image:'',imageAlt:'',buttonLabel:'Get involved',buttonUrl:'contact.html',hidden:false});sectionIndex=Math.max(0,list.length-2);view='pages';changed();render();break;
 case'upsection':case'downsection':if(!can('pages')||list[index].locked)return;{const next=index+(name==='upsection'?-1:1);if(next<0||next>=list.length||list[next].locked)return;checkpoint();[list[index],list[next]]=[list[next],list[index]];sectionIndex=next;changed();render();}break;
 case'duplicatesection':if(!can('pages')||list[index].locked)return;checkpoint();{const copy=clone(list[index]);copy.sourceId=copy.custom?undefined:copy.sourceId||copy.id;copy.id='copy-'+Date.now();copy.label=(copy.label||copy.title)+' (copy)';list.splice(index+1,0,copy);sectionIndex=index+1;changed();render();}break;
 case'hidesection':if(!can('pages')||list[index].locked)return;checkpoint();list[index].hidden=!list[index].hidden;changed();render();break;
 case'deletesection':if(!can('pages')||list[index].locked)return;if(await confirmChange('Delete this section?',`“${list[index].label||list[index].title}” will be removed from the draft. Use Undo to recover it before leaving this session.`)){checkpoint();list.splice(index,1);sectionIndex=Math.max(0,index-1);changed();render();}break;
 case'morelinks':linkLimit+=60;render();break;
 case'linksection':selectPage(index);sectionIndex=Number(node.dataset.section);view='pages';render();break;
 case'addnav':if(!can('navigation'))return;checkpoint();draft.navigation.push({id:'link-'+Date.now(),label:'New link',url:'contact.html'});changed();render();break;
 case'upnav':case'downnav':if(!can('navigation'))return;{const next=index+(name==='upnav'?-1:1);if(next<0||next>=draft.navigation.length)return;checkpoint();[draft.navigation[index],draft.navigation[next]]=[draft.navigation[next],draft.navigation[index]];changed();render();}break;
 case'deletenav':if(!can('navigation'))return;checkpoint();draft.navigation.splice(index,1);changed();render();break;
 case'previewshop':selectPage(draft.pages.findIndex(p=>p.file==='shop.html'));view='preview';render();break;
 case'addproduct':if(!can('products'))return;checkpoint();draft.products.push({id:'product-'+crypto.randomUUID(),name:'New product',price:0,category:'Apparel',description:'',image:'',imageAlt:'',colors:[{name:'White',hex:'#ffffff',image:'',alt:''}]});changed();render();break;
 case'deleteproduct':if(!can('products'))return;if(await confirmChange('Remove this product?','It will disappear from the shop after publishing. You can undo this change before saving.')){checkpoint();draft.products.splice(index,1);changed();render();}break;
 case'addcolor':if(!can('products'))return;checkpoint();(draft.products[index].colors||=[]).push({name:'New color',hex:'#ffffff',image:'',alt:''});changed();render();break;
 case'deletecolor':if(!can('products'))return;checkpoint();draft.products[index].colors.splice(Number(node.dataset.color),1);changed();render();break;
 case'uploadproduct':if(!can('products')||!can('media'))return;$('#product-upload').dataset.color=node.dataset.color??'';$('#product-upload').dataset.index=index;$('#product-upload').click();break;
 case'pickimage':imageTarget=node.dataset.path;view='media';render();break;
 case'useimage':if(!imageTarget||!can(imageTarget.split('.')[0]))return;checkpoint();setPath(draft,imageTarget,'/'+draft.media[index].url.replace(/^\//,''));view=imageTarget.startsWith('products.')?'shop':'pages';imageTarget=null;changed();render();break;
 case'moremedia':mediaLimit+=25;render();break;
 case'upload':replaceMedia=null;$('#media-upload').click();break;
 case'replacemedia':replaceMedia=index;$('#media-upload').click();break;
 case'editmedia':if(!can('media'))return;{const item=draft.media[index],alt=prompt('Image description (alt text)',item.alt);if(alt===null)return;const folder=prompt('Folder',item.folder);if(folder===null)return;checkpoint();item.alt=alt;item.folder=folder;changed();render();}break;
 case'deletemedia':if(!can('media'))return;{const item=draft.media[index],uses=mediaUsage(item.url);if(uses.length){toast(`This image is used in ${uses.length} places. Replace it before removing it from the library.`);return;}if(await confirmChange('Remove this image from the library?','The original file is retained on disk. This removes only its library entry and can be undone.')){checkpoint();draft.media.splice(index,1);changed();render();}}break;
 case'restore':if(dirty&&!await confirmChange('Replace unsaved changes?','Restoring a revision replaces the current working draft.'))return;await api('restore',{method:'POST',body:JSON.stringify({id:node.dataset.id,revision})});await load();toast('Previous draft restored. Review before publishing.');break;
 case'removeuser':if(await confirmChange('Remove this user?','Their account will be deleted and active sessions will be signed out.')){await api('users',{method:'PATCH',body:JSON.stringify({id:node.dataset.id,remove:true})});await load();toast('User removed.');}break;
 case'edituser':{const user=model.users.find(user=>user.id===node.dataset.id);const role=prompt('Role: Owner, Administrator, Editor or Viewer',user.role);if(role===null)return;const areas=prompt('Allowed areas, comma-separated (blank = role defaults): pages, navigation, theme, event, timing, media, products',user.areas?.join(', ')||'');if(areas===null)return;if(await confirmChange('Update access?',`Update ${user.name} to ${role}? Their active sessions will be signed out.`)){await api('users',{method:'PATCH',body:JSON.stringify({id:user.id,role,areas:areas.trim()?areas.split(',').map(x=>x.trim()):null})});await load();toast('User permissions updated.');}}break;
 }
}
document.addEventListener('click',async event=>{
 const nav=event.target.closest('[data-view]');const node=event.target.closest('[data-action]');
 try{if(nav){view=nav.dataset.view;render();return;}if(node&&!node.disabled)await action(node.dataset.action,node);}catch(error){toast(error.message);}
});
document.addEventListener('keydown',event=>{if(event.target.matches('.section-item')&&['Enter',' '].includes(event.key)){event.preventDefault();action('selectsection',event.target);}if((event.ctrlKey||event.metaKey)&&event.key==='s'&&draft){event.preventDefault();save().catch(error=>toast(error.message));}});
function setFormatting(node){
 const rawPath=node.dataset.formatPath;if(!can(rawPath.split('.')[0]))return;const path=formatKey(rawPath);
 draft.textStyles||={};draft.textStyles[path]||={};
 let value=node.dataset.formatValue??node.value;
 if(node.dataset.format==='fontSize')value=value?Number(value):'';
 if(value==='')delete draft.textStyles[path][node.dataset.format];else draft.textStyles[path][node.dataset.format]=value;
 if(!Object.keys(draft.textStyles[path]).length)delete draft.textStyles[path];changed();
}
document.addEventListener('click',event=>{
 const button=event.target.closest('button[data-format-path],button[data-format-reset]');if(!button)return;
 const path=button.dataset.formatPath||button.dataset.formatReset;if(!can(path.split('.')[0]))return;
 checkpoint();if(button.dataset.formatReset){if(draft.textStyles)delete draft.textStyles[formatKey(path)];changed();}else setFormatting(button);render();
});
document.addEventListener('keydown',event=>{
 const tab=event.target.closest('[role="tab"]');if(!tab||event.target!==tab)return;
 const count=draft.pages[pageIndex].sections.length;let index=Number(tab.dataset.index);
 if(event.key==='ArrowRight')index=(index+1)%count;else if(event.key==='ArrowLeft')index=(index+count-1)%count;else if(event.key==='Home')index=0;else if(event.key==='End')index=count-1;else if(!['Enter',' '].includes(event.key))return;
 event.preventDefault();sectionIndex=index;fieldQuery='';render();const next=document.querySelector('[role="tab"][aria-selected="true"]');next?.focus();next?.scrollIntoView({block:'nearest',inline:'nearest'});
});
document.addEventListener('focusin',event=>{if(event.target.matches('[data-bind],[data-format-path]'))checkpoint();});
document.addEventListener('input',event=>{
 const node=event.target;
 if(node.dataset.formatPath&&node.tagName!=='BUTTON'){setFormatting(node);return;}
 if(node.dataset.bind){const area=node.dataset.bind.split('.')[0];if(!can(area))return;let value=node.type==='number'?Number(node.value):node.value;if(node.hasAttribute('data-utc'))value=node.value?new Date(node.value+'Z').toISOString():'';setPath(draft,node.dataset.bind,value);changed();if(view==='appearance')updateContrast();}
 if(node.matches('[data-field-search]')){fieldQuery=node.value;const position=node.selectionStart;render();const search=$('[data-field-search]');search.focus();search.setSelectionRange(position,position);}
 if(node.matches('[data-link-search]')){linkQuery=node.value;linkLimit=60;const position=node.selectionStart;render();const search=$('[data-link-search]');search.focus();search.setSelectionRange(position,position);}
 if(node.matches('[data-media-search]')){mediaQuery=node.value;mediaLimit=25;const position=node.selectionStart;render();const search=$('[data-media-search]');search.focus();search.setSelectionRange(position,position);}
});
document.addEventListener('change',async event=>{
 const node=event.target;
 if(node.id==='product-upload'&&node.files[0])try{
  if(!can('products')||!can('media'))return;
  const index=Number(node.dataset.index),file=node.files[0],product=draft.products[index],color=node.dataset.color!==''?product.colors[Number(node.dataset.color)]:null,target=color||product;
  if(file.size>5*1024*1024)throw new Error('Choose an image smaller than 5 MB.');
  const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});
  const image=await api('upload',{method:'POST',body:JSON.stringify({data,alt:color?(color.alt||product.name+' - '+color.name):(product.imageAlt||product.name)})});
  checkpoint();draft.media.unshift(image);target.image='/'+image.url.replace(/^\//,'');if(color)color.alt=image.alt;else product.imageAlt=image.alt;changed();render();toast('Product photo uploaded. Save and publish when ready.');
 }catch(error){toast(error.message);}
 if(node.matches('[data-page-select]')){selectPage(node.value);render();}
 if(node.matches('[data-link-page]')){linkPage=node.value;linkLimit=60;render();}
 if(node.matches('[data-link-type]')){linkType=node.value;linkLimit=60;render();}
 if(node.matches('[data-preview-version]')){previewMode=node.value;render();}
 if(node.id==='media-upload'&&node.files[0])try{
  const file=node.files[0];if(file.size>5*1024*1024)throw new Error('Choose a PNG, JPEG or WebP smaller than 5 MB.');
  const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});
  const image=await api('upload',{method:'POST',body:JSON.stringify({data,alt:file.name.replace(/\.[^.]+$/,'')})});checkpoint();
  if(replaceMedia!==null){const old=draft.media[replaceMedia];draft.pages.forEach(p=>p.sections.forEach(s=>(s.fields||[]).forEach(f=>{if(f.attribute==='src'&&normalizePath(f.value)===normalizePath(old.url))f.value='/'+image.url;})));draft.products.forEach(product=>{if(normalizePath(product.image||'')===normalizePath(old.url))product.image='/'+image.url;for(const color of product.colors||[])if(normalizePath(color.image||'')===normalizePath(old.url))color.image='/'+image.url;});draft.media[replaceMedia]=image;replaceMedia=null;}else draft.media.unshift(image);
  changed();render();toast('Image uploaded. Save the draft to keep its library entry.');
 }catch(error){toast(error.message);}
});
document.addEventListener('submit',async event=>{
 const form=event.target;
 if(form.matches('[data-auth]')){event.preventDefault();const input=Object.fromEntries(new FormData(form));const submit=form.querySelector('button');submit.disabled=true;try{auth=await api(form.dataset.auth,{method:'POST',body:JSON.stringify(input)});await load();}catch(error){authScreen(form.dataset.auth==='setup',error.message);}return;}
 if(form.matches('[data-user-form]')){event.preventDefault();try{await api('users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});await load();toast('Team member created.');}catch(error){toast(error.message);}}
});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
try{const session=await api('session');auth=session;if(session.user){await load();}else authScreen(session.setup);}catch(error){authScreen(false,error.message);}
